-- insert-palma-centers.sql
-- Inserta los 75 centros de educacion infantil (0-3 anos) del
-- termino municipal de Palma (capital + barrios/pedanias del mismo termino
-- municipal: Son Ferriol, S'Arenal, Es Coll d'en Rabassa, Can Pastilla,
-- Establiments, Es Pil.lari, Sant Jordi, Ciutat Jardi, Es Secar de la Real,
-- El Terreno, Son Espanyolet) investigados y humanizados en este sprint.
-- Distribucion: 54 guarderia privada + 14 escuela-infantil publica (11 EIEL
-- del Patronat Municipal d'Escoles d'Infants + Virgen de Loreto [EIEL segun
-- el directorio oficial, no listada entre las 12 escuelas del PMEI en su
-- propia web] + Verge de la Salut y Paula Torres, de titularidad de la
-- Conselleria d'Educacio i Universitats) + 7 escuela-infantil concertada
-- (CCEI).
-- Fuente principal: endpoint publico de la herramienta Oferta Educativa
-- (GestIB) del Govern de les Illes Balears, complementado con
-- palmaescolesinfants.cat (Patronat Municipal d'Escoles d'Infants, Ajuntament
-- de Palma) para las escuelas municipales, y con las webs oficiales de 6
-- centros privados/concertados verificados individualmente. Ver
-- docs/data-sources-palma.md.
--
-- Ninguna fuente disponible incluye distritos formales de Palma para estos
-- centros, por lo que district queda NULL en los 75 centros;
-- neighborhood_barrio recoge el barrio/pedania cuando la fuente oficial lo
-- distingue de "Palma" capital (14 de 75 centros).
--
-- 2 centros nuevos del Patronat (Son Dameto Dalt, Son Gibert), autorizados
-- pero aun no operativos a fecha de generacion de este dataset (apertura
-- prevista para el curso 2026-2027), NO se incluyen en este INSERT - ver
-- data/enrichment/palma-centers-excluded.json.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por
-- RLS hasta cambiarlos a 'published' manualmente, igual que se hizo con
-- Madrid, Barcelona, Valencia y Murcia).
-- No toca ningun centro de Madrid, Barcelona, Valencia, Zaragoza ni Murcia.
-- No borra ni modifica filas existentes fuera de estos slugs (upsert por
-- slug: si un slug ya existe se actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar. NO EJECUTADO por el
-- agente que lo genero.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "palma" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('palma', 'Palma', 'Illes Balears', 'Illes Balears')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('angelets-de-llum-palma', 'Angelets de Llum', 'guarderia', 'privado', 'Carrer JORGE SEPULVEDA, 5', '07010', 'palma', 'Palma', NULL, NULL, NULL, 39.5897559, 2.6451113, '971202523', 'ceiangeletsdellum@gmail.com', 'https://www.angeletsdellum.com', 0, 36, NULL, ARRAY['comedor','verano-campamentos']::text[], 'Angelets de Llum, en Carrer JORGE SEPULVEDA, 5, 07010, en Palma, es un centro privado de educación infantil de primer ciclo (0-3 años). Su propia web confirma comedor y campamentos de verano. Antes de solicitar plaza, recomendamos contactar con el centro para conocer disponibilidad y condiciones actuales.', 'Angelets de Llum es un centro privado de educación infantil de primer ciclo situado en Carrer JORGE SEPULVEDA, 5, 07010, en Palma, dedicado a niños de 0 a 3 años. Su presencia en el directorio de centros educativos del Govern de les Illes Balears confirma su autorización como centro de esta etapa.

Según la información publicada en su propia web, el centro ofrece servicio de comedor y escuela de verano para los meses estivales.

Estos datos proceden directamente de la web oficial del centro, por lo que pueden variar de un curso a otro. Antes de solicitar plaza, recomendamos confirmar con Angelets de Llum la disponibilidad, precios y condiciones actualizadas de matrícula.', '{}'::text[], '[{"question":"¿Dónde está ubicado Angelets de Llum?","answer":"El centro se encuentra en Carrer JORGE SEPULVEDA, 5, 07010, en Palma."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público, concertado o privado?","answer":"Es un centro de titularidad privada, según el directorio oficial de centros educativos del Govern de les Illes Balears."},{"question":"¿Qué servicios ofrece Angelets de Llum?","answer":"Según su propia web, el centro confirma comedor y campamentos de verano."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 971202523, o escribir a ceiangeletsdellum@gmail.com, o visitar https://www.angeletsdellum.com."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www3.caib.es/xestibback/external/llistes/llistaCentresDirectori.json', ARRAY['https://www.angeletsdellum.com']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
('asima-palma', 'Asima', 'guarderia', 'privado', 'Carrer GREMI DE BOTERS, 21', '07009', 'palma', 'Palma', NULL, NULL, NULL, 39.6073087, 2.6674578, '971433493', 'escoleta@asima.com', NULL, 0, 36, NULL, '{}'::text[], 'Asima aparece en el directorio oficial de centros educativos del Govern de les Illes Balears como centro privado de educación infantil, con dirección en Carrer GREMI DE BOTERS, 21, 07009, en Palma. Atiende a niños de 0 a 3 años. Para conocer horarios, servicios y disponibilidad de plazas, lo recomendable es ponerse en contacto con el centro.', NULL, '{}'::text[], '[{"question":"¿Dónde está ubicado Asima?","answer":"El centro se encuentra en Carrer GREMI DE BOTERS, 21, 07009, en Palma."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público, concertado o privado?","answer":"Es un centro de titularidad privada, según el directorio oficial de centros educativos del Govern de les Illes Balears."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 971433493, o escribir a escoleta@asima.com."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del directorio oficial de centros educativos del Govern de les Illes Balears. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www3.caib.es/xestibback/external/llistes/llistaCentresDirectori.json', '{}'::text[], '2026-07-12'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('atlas-escoleta-palma', 'Atlas Escoleta', 'guarderia', 'privado', 'Carrer ANDREU TORRENS, 5', '07011', 'palma', 'Palma', NULL, NULL, NULL, 39.5794786, 2.6403894, '653386808', 'atlasescoleta@hotmail.com', NULL, 0, 36, NULL, '{}'::text[], 'Con dirección en Carrer ANDREU TORRENS, 5, 07011, en Palma, Atlas Escoleta es un centro privado de educación infantil de primer ciclo, según consta en el directorio oficial de centros del Govern de les Illes Balears. El directorio no detalla servicios adicionales, por lo que recomendamos confirmarlos directamente con el centro.', NULL, '{}'::text[], '[{"question":"¿Dónde está ubicado Atlas Escoleta?","answer":"El centro se encuentra en Carrer ANDREU TORRENS, 5, 07011, en Palma."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público, concertado o privado?","answer":"Es un centro de titularidad privada, según el directorio oficial de centros educativos del Govern de les Illes Balears."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 653386808, o escribir a atlasescoleta@hotmail.com."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del directorio oficial de centros educativos del Govern de les Illes Balears. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://www3.caib.es/xestibback/external/llistes/llistaCentresDirectori.json', '{}'::text[], '2026-07-12'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
